#include <stdio.h>
#include <string.h>
#include <ctype.h>

int main(int argc, char **argv) {
    const char *input;
    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }
    input = argv[1];
    // Limit to 1024 characters as the original binary does.
    size_t len = strlen(input);
    if (len > 1024) len = 1024;

    char output[1025]; // enough for trimmed string + null
    size_t out_idx = 0;
    int have_output = 0; // whether any non‑whitespace has been copied yet
    int prev_was_space = 0;

    for (size_t i = 0; i < len; ++i) {
        char c = input[i];
        // treat space, tab, newline, carriage return, vertical tab, form feed as whitespace
        int is_ws = (c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\v' || c == '\f');
        if (is_ws) {
            if (have_output && !prev_was_space) {
                // collapse consecutive whitespace to a single space
                output[out_idx++] = ' ';
                prev_was_space = 1;
            }
            // otherwise skip (leading whitespace or multiple spaces)
        } else {
            output[out_idx++] = c;
            have_output = 1;
            prev_was_space = 0;
        }
    }

    // Trim possible trailing space added by the loop (if the last characters were whitespace)
    if (out_idx > 0 && output[out_idx - 1] == ' ') {
        --out_idx;
    }
    output[out_idx] = '\0';

    if (out_idx == 0) {
        puts("EMPTY");
    } else {
        puts(output);
    }
    return 0;
}
